// =========================================================================
// ⚡ ÖN BELLEKLENMİŞ VE OPTİMİZE EDİLMİŞ HAVUZLAR (O(1) Anında Erişim)
// =========================================================================

export const SUPER_LIG_PLAYERS: Player[] = PLAYERS.filter((p) =>
  p.career.some((c) => c.league === "Türkiye")
);

export const WORLD_PLAYERS: Player[] = PLAYERS.filter(
  (p) => !p.career.some((c) => c.league === "Türkiye") || p.career.length > 2
);

export const POOL_COUNTS = {
  ALL: PLAYERS.length,
  SUPER_LIG: SUPER_LIG_PLAYERS.length,
  WORLD: WORLD_PLAYERS.length,
} as const;

// Arama motoru için önceden normalize edilmiş ultra hızlı indeks
export interface IndexedPlayerItem {
  player: Player;
  searchKey: string;
}

export const INDEXED_SEARCH_PLAYERS: IndexedPlayerItem[] = PLAYERS.map((player) => ({
  player,
  searchKey: `${player.name.toLocaleLowerCase("tr")} ${
    player.fullName ? player.fullName.toLocaleLowerCase("tr") : ""
  }`,
}));
